-- Commerce fiscal -- generated by noctusai_lib.domain.commerce.fiscal_sql (do not hand-edit)

SET search_path = commerce, public;

-- Fiscal identity + NFS-e mode on the store profile.
ALTER TABLE commerce.commerce_store_profiles ADD COLUMN IF NOT EXISTS inscricao_municipal TEXT;
ALTER TABLE commerce.commerce_store_profiles ADD COLUMN IF NOT EXISTS inscricao_estadual TEXT;
ALTER TABLE commerce.commerce_store_profiles ADD COLUMN IF NOT EXISTS municipio_ibge TEXT CHECK (municipio_ibge IS NULL OR municipio_ibge ~ '^[0-9]{7}$');
ALTER TABLE commerce.commerce_store_profiles ADD COLUMN IF NOT EXISTS nfse_mode TEXT CHECK (nfse_mode IS NULL OR nfse_mode IN ('nacional', 'municipal'));
ALTER TABLE commerce.commerce_store_profiles ADD COLUMN IF NOT EXISTS nfse_cutover JSONB NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE commerce.commerce_store_profiles ADD COLUMN IF NOT EXISTS invoice_company_ref TEXT;
ALTER TABLE commerce.commerce_store_profiles ADD COLUMN IF NOT EXISTS certificate_valid_until TIMESTAMPTZ;
ALTER TABLE commerce.commerce_store_profiles ADD COLUMN IF NOT EXISTS certificate_cnpj TEXT;
ALTER TABLE commerce.commerce_store_profiles ADD COLUMN IF NOT EXISTS auto_issue_invoices BOOLEAN NOT NULL DEFAULT false;
-- D37: Simples/MEI must issue NFS-e via the Emissor Nacional; a municipal mode is unrepresentable.
ALTER TABLE commerce.commerce_store_profiles DROP CONSTRAINT IF EXISTS commerce_store_profiles_nfse_regime_ck;
ALTER TABLE commerce.commerce_store_profiles ADD CONSTRAINT commerce_store_profiles_nfse_regime_ck
    CHECK (nfse_mode IS NULL OR NOT (tax_regime IN ('mei', 'simples') AND nfse_mode = 'municipal'));

-- Invoices: one row per fiscal document attempt. ref = OUR idempotency key; pdf_path/xml_path = private-bucket keys.
CREATE TABLE IF NOT EXISTS commerce.commerce_invoices (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id              UUID NOT NULL,
    order_id            UUID NOT NULL REFERENCES commerce.commerce_orders(id) ON DELETE CASCADE,
    kind                TEXT NOT NULL CHECK (kind IN ('nfe', 'nfse')),
    seq                 INTEGER NOT NULL DEFAULT 1 CHECK (seq >= 1),
    ref                 TEXT NOT NULL CHECK (ref ~ '^[A-Za-z0-9_-]{1,64}$'),
    status              TEXT NOT NULL DEFAULT 'processing' CHECK (status IN ('processing', 'authorized', 'rejected', 'cancelled', 'error')),
    provider            TEXT,
    number              TEXT,
    series              TEXT,
    access_key          TEXT,
    verification_code   TEXT,
    pdf_path            TEXT,
    xml_path            TEXT,
    rejection           JSONB,
    cancel_reason       TEXT,
    cancel_requested_at TIMESTAMPTZ,
    issued_at           TIMESTAMPTZ,
    cancelled_at        TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (org_id, ref),
    UNIQUE (order_id, kind, seq)
);
CREATE INDEX IF NOT EXISTS idx_commerce_invoices_order ON commerce.commerce_invoices (order_id);
CREATE INDEX IF NOT EXISTS idx_commerce_invoices_org_status ON commerce.commerce_invoices (org_id, status);
ALTER TABLE commerce.commerce_invoices ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "commerce_invoices_select_own_org" ON commerce.commerce_invoices;
CREATE POLICY "commerce_invoices_select_own_org" ON commerce.commerce_invoices FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.commerce_invoices;
CREATE POLICY "service_role_bypass" ON commerce.commerce_invoices FOR ALL TO service_role USING (true) WITH CHECK (true);
